let activeSidebar;
function activate(context){let sidebar;try{sidebar=new Sidebar(context);}catch(e){vscode.window.showErrorMessage(product.display_name+tr(' 本地私稿不可用：')+safeCode(e));return;}
  activeSidebar=sidebar;
  const commands={showChat:()=>vscode.commands.executeCommand('eeasCompanion.chat.focus'),configure:()=>sidebar.configure(),start:()=>sidebar.start(),connect:()=>sidebar.connect(true),reveal:()=>sidebar.reveal(),attachSelection:()=>sidebar.attach(),compareSaved:()=>sidebar.diff(),previewMarkdown:()=>sidebar.markdown(),repairPair:()=>sidebar.repairPair()};
  context.subscriptions.push(sidebar,vscode.window.registerWebviewViewProvider('eeasCompanion.chat',sidebar),vscode.workspace.registerTextDocumentContentProvider('eeas-readonly',{provideTextDocumentContent:uri=>sidebar.readonlyDocs.get(uri.path.replace(/^\//,''))||tr('此只读快照已释放，请重新比较。')}));
  context.subscriptions.push(vscode.workspace.registerTextDocumentContentProvider(SCHEME,{provideTextDocumentContent:(uri,cancellation)=>{try{return sidebar.diffDocuments.provide(uri,cancellation);}catch(e){if(e.code==='DIFF_SNAPSHOT_EXPIRED')throw Object.assign(new Error(tr('只读快照已释放，请重新读取')),{code:e.code});throw e;}}}));
  for(const [name,fn]of Object.entries(commands))context.subscriptions.push(vscode.commands.registerCommand('eeasCompanion.'+name,()=>Promise.resolve(fn()).catch(e=>vscode.window.showErrorMessage(e.message||safeCode(e)))));
  context.subscriptions.push(vscode.workspace.onDidChangeConfiguration(e=>{if(e.affectsConfiguration('eeasCompanion.installDirectory')||e.affectsConfiguration('eeasCompanion.dataDirectory')){sidebar.cancelConnection({resetScope:true});sidebar.connection='APP_NOT_CONNECTED';sidebar.notice='连接位置已变化，请显式重新连接。';sidebar.render();}else if(e.affectsConfiguration('eeasCompanion.language'))sidebar.render();}));
}
async function deactivate(){if(activeSidebar){activeSidebar.controller.flushOriginalWorkInputs();await activeSidebar.controller.workCases.flushAll();await activeSidebar.controller.workRetests.flushAll();await activeSidebar.controller.workSources.flushAll();await activeSidebar.controller.workDeliveries.flushAll();await activeSidebar.controller.nativeExports.flushAll();await activeSidebar.controller.workMaintenance.flushAll();activeSidebar.dispose();activeSidebar=null;}}
module.exports={activate,deactivate,parseMessage,Sidebar};
